const c = $('Supabase: get cloth').first().json[0];
const style = c.artistic_styles?.name || 'abstract';
return [{ json: { cloth_id: c.id, name: c.name,
  prompt: `original artwork born from this message: \u00ab${c.message}\u00bb. artistic style: ${style}. no text, no letters, no words in the image. museum-grade composition, bold, printable on a garment, strong silhouette, high contrast.`
}}];

// why: l'api storage attend du binaire, pas du base64
const out = [];
for (const item of $input.all()) {
  const { cloth_id, idx, b64, name } = item.json;
  const path = `${cloth_id}/concept-${idx}.png`;
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://abujjbkbbiumxrokozph.supabase.co/storage/v1/object/streetwear-generations/${path}`,
    headers: { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'image/png', 'x-upsert': 'true' },
    body: Buffer.from(b64, 'base64'),
  });
  // url signée 7 jours pour telegram + curation
  const signed = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://abujjbkbbiumxrokozph.supabase.co/storage/v1/object/sign/streetwear-generations/${path}`,
    headers: { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'application/json' },
    body: { expiresIn: 604800 }, json: true,
  });
  out.push({ json: { cloth_id, name, idx, storage_path: path, image_url: 'https://abujjbkbbiumxrokozph.supabase.co/storage/v1' + signed.signedURL } });
}
return out;

// why: un seul node pour insérer les 3 concepts puis envoyer l'album + clavier de curation
const items = $input.all().map(i => i.json);
const cloth_id = items[0].cloth_id, name = items[0].name;
const inserted = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://abujjbkbbiumxrokozph.supabase.co/rest/v1/cloth_concepts',
  headers: { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'application/json', Prefer: 'return=representation' },
  body: items.map(i => ({ cloth_id: i.cloth_id, image_url: i.image_url, storage_path: i.storage_path })), json: true,
});
await this.helpers.httpRequest({
  method: 'PATCH',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${cloth_id}`,
  headers: { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'application/json' },
  body: { status: 'curation' }, json: true,
});
const cloth = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${cloth_id}&select=message,name,size`,
  headers: { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}` }, json: true,
});
const tg = `https://api.telegram.org/bot${$vars.TG_TOKEN}`;
await this.helpers.httpRequest({ method: 'POST', url: `${tg}/sendMediaGroup`, json: true, body: {
  chat_id: $vars.TG_CURATOR_CHAT,
  media: inserted.map((c, i) => ({ type: 'photo', media: c.image_url, caption: i === 0 ? `\u3010${cloth[0].name}\u3011 ${cloth[0].size}\n\u00ab${cloth[0].message.slice(0, 800)}\u00bb` : undefined })),
}});
await this.helpers.httpRequest({ method: 'POST', url: `${tg}/sendMessage`, json: true, body: {
  chat_id: $vars.TG_CURATOR_CHAT,
  text: `curate \u3010${cloth[0].name}\u3011`,
  reply_markup: { inline_keyboard: [
    inserted.map((c, i) => ({ text: String(i + 1), callback_data: `pick:${c.id}` })),
    [{ text: 'REGEN', callback_data: `regen:${cloth_id}` }],
  ]},
}});
return [{ json: { ok: true, cloth_id } }];
